<?php
namespace App\Http\Controllers;
use App\Models\PayrollSheet;use App\Services\Payroll\PayrollAccessService;use Barryvdh\DomPDF\Facade\Pdf;use Illuminate\Http\Request;use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
class ExportController extends Controller {
 public function excel(Request $r,PayrollSheet $sheet,PayrollAccessService $a){abort_unless($a->canView($r->user(),$sheet)&&$sheet->finalized_at,403);$sheet->load(['period.columns','rows.cells']);$book=new Spreadsheet();$ws=$book->getActiveSheet();$heads=['نام','نام خانوادگی','شماره پرسنلی','کد ملی',...$sheet->period->columns->pluck('title')->all()];foreach($heads as $i=>$h)$ws->setCellValue([$i+1,1],$h);foreach($sheet->rows as $ri=>$row){$vals=[$row->first_name_snapshot,$row->last_name_snapshot,$row->personnel_number_snapshot,$row->national_id_snapshot];foreach($sheet->period->columns as $col){$c=$row->cells->firstWhere('payroll_column_id',$col->id);$vals[]=$c?->{match($col->value_type){'number'=>'number_value','date'=>'date_value','boolean'=>'boolean_value',default=>'text_value'}};}foreach($vals as $ci=>$v)$ws->setCellValue([$ci+1,$ri+2],$v);} $tmp=tempnam(sys_get_temp_dir(),'tukahr');(new Xlsx($book))->save($tmp);return response()->download($tmp,"tukahr-{$sheet->id}.xlsx")->deleteFileAfterSend(true);}
 public function pdf(Request $r,PayrollSheet $sheet,PayrollAccessService $a){abort_unless($a->canView($r->user(),$sheet)&&$sheet->finalized_at,403);$sheet->load(['period.columns','rows.cells','approvals']);return Pdf::loadView('payroll.pdf',['sheet'=>$sheet])->setPaper('a4','landscape')->stream("tukahr-{$sheet->id}.pdf");}
}
